  [MeasureTheory.IsProbabilityMeasure P] {O : ℕ → Ω → Unit} {A : ℕ → Ω → 𝓐} {Y : ℕ → Ω → ℝ}
  {alg : Learning.Algorithm Unit 𝓐 ℝ} [StandardBorelSpace 𝓐] [Nonempty 𝓐]
  (h : Learning.IsAlgEnvSeq O A Y alg (Learning.stationaryEnv ν) P) (k : 𝓐) (n : ℕ) :
  AlphaRAR.aRTSSelProb A k h.filtration P (n + 1) =ᵐ[P] fun ω =>
    (((alg.policy (n + 1)) (Learning.history O A Y (n + 1) ω, ())) {k}).toReal

